  // Path to the file to write (relative or absolute)
  path: string;
}): Promise<string>; };
```

Run JavaScript code to orchestrate/compose tool calls
- Evaluates the provided JavaScript code in a fresh QuickJS sandbox as the body of an async function: top-level `await` and `return` work.
- All nested tools are available on the global `tools` object, for example `await tools.read(...)`. Tool names are exposed as normalized JavaScript identifiers, for example `await tools.mcp__ologs__get_profile(...)`.
- Nested tool methods take an object as their input argument.
- Nested tools return either an object or a string, based on the description.
- A nested tool call that fails, is blocked, or gets invalid arguments rejects with an Error carrying the tool's error text.
- Runs raw JavaScript -- no Node, no file system, no network access, no timers.
- Accepts raw JavaScript source text, not JSON, quoted strings, or markdown code fences.
- You may optionally start the tool input with a first line like `// @options: {"max_output_tokens": 1000, "timeout_ms": 60000}`.
- `max_output_tokens` sets the token budget for the script's output. Defaults to 10000 tokens.
- `timeout_ms` sets a hard deadline for the whole script. By default there is none.
- When the JS code is fully evaluated, calls that are still running are cancelled and unawaited promises are silently discarded.
- Tool calls are real and have side effects. If the script fails partway, earlier calls are not undone.
- Scripts have a 256 MB memory limit; exceeding it throws `InternalError: out of memory`. Filter or aggregate large data instead of accumulating it.

- Global helpers:
- `exit()`: Immediately ends the current script successfully (like an early return from the top level).
- `text(value: string | number | boolean | undefined | null)`: Appends a text item. Non-string values are stringified with `JSON.stringify(...)` when possible.
- `image(imageUrlOrItem: string | { image_url: string } | ImageContent)`: Appends an image item. `image_url` should be a base64-encoded `data:` URL. To forward an MCP tool image, pass an individual `ImageContent` block from `result.content`, for example `image(result.content[0])`.
- `store(key: string, value: any)`: stores a serializable value under a string key for later `codemode` calls in the same session. Storing `undefined` deletes the key. Writes are kept only if the script succeeds.
- `load(key: string)`: returns the stored value for a string key, or `undefined` if it is missing.
- `ALL_TOOLS`: metadata for the enabled nested tools as `{ name, description }` entries.
- `searchTools(query: string, options?: { limit?: number; namespace?: string })`: resolves to the nested tools that best match the query (BM25, default limit 8), as `{ name, description }` entries like `ALL_TOOLS`.
- `describeTool(name: string)`: resolves to the description and declaration of a nested tool, or `undefined`.
- `console.log(...)` and the other `console` methods append a text item like `text()`.
- `return value` at the top level appends the value like `text()`.

Model API:
```ts
type ModelType = "chat" | "image" | "classifier";
/** A model catalog entry. `provider` and `id` identify it; the other fields depend on the type. */
interface ModelInfo {
  type?: ModelType;
  provider: string;
  id: string;
  name: string;
  api: string;
  input: ("text" | "image")[];
  contextWindow?: number;
  [key: string]: unknown;
}
type ClassifierQuestion =
  | { type: "choice"; instructions: string; criteria: Record<string, string> }
  | { type: "score"; instructions: string; criteria: string[] }
  | { type: "bool"; instructions: string; criteria: { true: string; false: string } };
type ClassifierAnswer =
  | { type: "choice"; choice: string; probabilities: Record<string, number>; confidence: number }
  | { type: "score"; score: number; confidence: number }
  | { type: "bool"; probability: number };
interface ClassifierContext {
  state: Record<string, unknown>;
  questions: Record<string, ClassifierQuestion>;
}
interface ClassifierResult {
  api: string;
  provider: string;
  model: string;
  answers: Record<string, ClassifierAnswer>;
  /** Set when the service reports token counts. Cost is in USD. */
  usage?: { input: number; output: number; totalTokens: number; cost: { total: number } };
  stopReason: "stop" | "error" | "aborted";
  errorMessage?: string;
  timestamp: number;
}

declare const models: {
  /** Every known model of a type, optionally for one provider. */
  getModelsOfType(type: ModelType, provider?: string): Promise<ModelInfo[]>;
  /** Models of a type whose provider has working credentials. */
  getAvailableOfType(type: ModelType, provider?: string): Promise<ModelInfo[]>;
  /** One catalog entry, or undefined. */
  getModelOfType(type: ModelType, provider: string, id: string): Promise<ModelInfo | undefined>;
  /** Run a classifier model on one state. Only `provider` and `id` of `model` are used. Provider errors do not throw: check `stopReason` and `errorMessage`. */
  classify(model: ModelInfo, context: ClassifierContext): Promise<ClassifierResult>;
};
```

Mark an active /goal complete only when the latest effective Goal contract explicitly says Goal mode is active, supplies the matching current goal_id, and every requirement is verified. Tool visibility alone does not activate Goal mode. Never call for ordinary work, partial progress, blockers, failures, or unverified work.

codemode tool declaration:
```ts
declare const tools: { goal_complete(args: {
  // The exact goal_id shown in the current active /goal prompt. Used only to reject stale completion calls from older turns.
  goal_id: string;
  // State what was completed and what evidence verified it. Do not use this tool to report partial progress, blockers, failures, or remaining work.
  summary: string;
}): Promise<string>; };
```

Stop an active /goal only when the latest effective Goal contract explicitly says Goal mode is active, supplies the matching current goal_id, and the same evidenced external blocker recurred for at least three consecutive Goal turns. Tool visibility alone does not activate Goal mode. Never call for ordinary clarification, uncertainty, incomplete work, or recoverable failures.

codemode tool declaration:
```ts
declare const tools: { goal_blocked(args: {
  // Concrete evidence from the repeated attempts that proves the impasse.
  evidence: string;
  // The exact goal_id shown in the current active /goal prompt.
  goal_id: string;
  // The specific user or external action required to unblock the goal.
  reason: string;
  // Number of separate turns spent trying to resolve this same blocker.
  repeated_turns: number;
}): Promise<string>; };
```

Keep an active /goal quiet only when the latest effective Goal contract explicitly says Goal mode is active, supplies the matching current goal_id, and progress depends on an arranged external wake event or one safety deadline. Tool visibility alone does not activate Goal mode. Call goal_wait alone. Requests below 10000ms are clamped to 10000ms. Never call for ordinary unfinished work.

codemode tool declaration:
```ts
declare const tools: { goal_wait(args: {
  // The exact goal_id shown in the current active /goal prompt.
  goal_id: string;
  // Why the goal is waiting and which external event should wake it.
  reason: string;
  // Optional safety deadline in milliseconds that requests one continuation if no wake message arrives. Values below 10000 are accepted but clamped to 10000.
  resume_after_ms?: number;
}): Promise<string>; };
```

Run a JavaScript workflow that delegates work to subagents with agent(), optionally composing calls with parallel() and pipeline().

codemode tool declaration:
```ts
declare const tools: { workflow(args: {
  // Retry attempts for recoverable agent failures such as timeout, connection failure, or empty assistant output. Default 0 unless configured.
  agentRetries?: number;
  // Timeout per agent in milliseconds. Omit to use configured `defaultAgentTimeoutMs`; without one, there is no hard timeout. Set only when the user asks to bound time.
  agentTimeoutMs?: number;
  // Optional JSON value exposed to the workflow script as global `args`.
  args?: { [key: string]: unknown; };
  // Run the workflow in the background. Default: true — the tool returns immediately with a run ID, the turn ends so the user isn't blocked, and the result is delivered back into the conversation when it finishes. Set to false only when you need the result inline in this same turn (the call will block until the workflow completes).
  background?: boolean;
  // Maximum concurrent agents for this run. Clamped to the runtime maximum. Use when provider/transport stability matters.
  concurrency?: number;
  // Agent cap (1000 default; safety). Count: verify=reviewers, judgePanel=entries×judges, completenessCheck=1. Retries add no slots. Lower for dynamic fan-out; large fan-outs need explicit user intent.
  maxAgents?: number;
  // Run a saved or built-in workflow by name instead of `script`; its args go in `args`. Built-ins: deep-research, adversarial-review, code-review, multi-perspective, codebase-audit — see the workflow-patterns skill for each one's args. A same-named saved workflow wins. Not combinable with resumeFromRunId.
  name?: string;
  // Resume a prior run (this ID) with an edited `script` instead of starting a new run. Unchanged agent() calls replay from that run's cache; the first changed/new call onward re-runs. Calls match by position: keep earlier good calls identical and in order. Always background.
  resumeFromRunId?: string;
  // Raw JavaScript workflow script, with no Markdown fences. Required unless `name` is given. First statement: export const meta = { name: 'short_snake_case', description: 'non-empty description' }. Add phases: [{ title: 'Phase' }] only when the workflow has named phases, and declare only phases it will use. With multiple phases, call phase('Exact Title') before each phase's work or set `phase` in the agent options. Use `await workflow(savedName, childArgs)` to run a saved workflow inline; nesting is limited to one level and shares the parent run's concurrency, agent, and token limits. Optional quality helpers include verify(), judgePanel(), loopUntilDry(), and completenessCheck(). Optional control helpers include retry() and gate(); budget exposes total, spent(), and remaining(), and phase('Name', { budget: N }) sets a phase token limit. The optional `agentType` option selects a named user or project definition that can bind tools, a model, and role instructions; use it only when its name and purpose are provided in context. Its bound model overrides `tier`; an explicit `model` overrides both. Use plain JavaScript only; imports, require(), filesystem modules, Date.now(), Math.random(), and new Date() are unavailable. Use phase('Name'), agent(prompt, opts), parallel(arrayOfFunctions), pipeline(items, ...stages), log(message), args, cwd, process.cwd(), and budget. The workflow must call agent() at least once. parallel() requires functions, not promises, and returns results in input order: await parallel(items.map(item => () => agent(...))). pipeline(items, ...stages) runs stages sequentially for each item while items proceed concurrently; each stage receives (previousValue, originalItem, index).
  script?: string;
  // Optional user-requested soft spend gate, not a planning target. Do not set `tokenBudget` unless the user explicitly supplies a cap or asks you to choose one; never infer or invent one from task size. If omitted, the configured `defaultTokenBudget` applies; without one, the run is unlimited. Reaching the gate blocks later `agent()` calls; concurrent in-flight work can overshoot.
  tokenBudget?: number;
}): Promise<string>; };
```

List and inspect workflow runs, or pause, resume, and stop them without asking the user to run slash commands.

codemode tool declaration:
```ts
declare const tools: { workflow_control(args: {
  // list = all runs (no runId); status/pause/resume/stop act on one run and require runId.
  action: "list" | "status" | "pause" | "resume" | "stop";
  // Exact durable checkpoint ID with an attached controller response. For resume only.
  checkpointId?: string;
  // Canonical workflow run ID. Required for status, pause, resume, and stop; omit for list.
  runId?: string;
}): Promise<string>; };
```

